actions.script:
const out = ec.service.sync().name('org.moqui.impl.VoicemailServices.get#Voicemail').parameter('voicemailId', voicemailId || '')
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
const caps = ec.service.sync().name('org.moqui.impl.VoiceServices.get#VoiceCapabilities').requireNewTransaction(true).disableAuthz().call() || {}
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, voicemail: out.voicemail || null, canCall: !!caps.active})

const out = ec.service.sync().name('org.moqui.impl.VoicemailServices.get#VoicemailAudio').parameter('voicemailId', voicemailId || '')
    .requireNewTransaction(true).disableAuthz().call() || {}
const refused = ec.message.hasError() || !out.location
ec.message.clearErrors()
if (refused) ec.web.sendJsonResponse({})
else ec.web.sendResourceResponse(out.location, String(inline) === 'true')

const out = ec.service.sync().name('org.moqui.impl.VoicemailServices.mark#VoicemailHeard').parameters({voicemailId: voicemailId || '',
    heard: String(heard) !== 'false'}).requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, voicemail: out.voicemail || null})

const out = ec.service.sync().name('org.moqui.impl.VoicemailServices.delete#Voicemail').parameter('voicemailId', voicemailId || '')
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, trashed: !!out.trashed, deleted: !!out.deleted})

const out = ec.service.sync().name('org.moqui.impl.VoicemailServices.restore#Voicemail').parameter('voicemailId', voicemailId || '')
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, voicemail: out.voicemail || null})

const out = ec.service.sync().name('org.moqui.impl.VoicemailServices.retry#VoicemailTranscript').parameter('voicemailId', voicemailId || '')
    .requireNewTransaction(true).disableAuthz().call() || {}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || null, errors, voicemail: out.voicemail || null})

const vm = ec.service.sync().name('org.moqui.impl.VoicemailServices.get#Voicemail').parameter('voicemailId', voicemailId || '')
    .requireNewTransaction(true).disableAuthz().call() || {}
let out = {}
if (vm.voicemail && vm.voicemail.fromNumber) {
    out = ec.service.sync().name('org.moqui.impl.VoiceServices.place#PhoneCall').parameters({phoneNumber: vm.voicemail.fromNumber,
        idempotencyKey: idempotencyKey || null}).requireNewTransaction(true).disableAuthz().call() || {}
} else if (!ec.message.hasError()) {
    ec.message.addError(ec.l10n.localize('This caller left no number'))
}
const errors = ec.message.hasError() ? ec.message.errorsString : null
ec.message.clearErrors()
ec.web.sendJsonResponse({reasonCode: out.reasonCode || vm.reasonCode || null, errors, callSessionId: out.callSessionId || null})
